import base64,hashlib,json,os,socket
from pathlib import Path
payload=json.loads('{"RELEASE.json": {"sha256": "bb4558fcc00ec7d0a3c3e9dc1d5c8db4ef70e8a3df998ae9bf685f47423cc66d", "base64": ""}, "RECEIPT.json": {"sha256": "77a66ea19558515c0981838a24dab65da29e27107a4a29903a1cad8e707cb5ee", "base64": ""}, "REVIEW.md": {"sha256": "64bb31cf5043cb9fb010e49a1f822979116cdf1e4694019504871738d40869fb", "base64": ""}}')
assert socket.gethostname().split('.')[0]=='h100-9'
d=Path('/dataset/shaoshitong/search-r1-rl/tree-grpo/instruct300/probability-probe-release-r2-audits');d.mkdir(parents=True,exist_ok=True)
out={}
for name,item in payload.items():
 b=base64.b64decode(item['base64']); assert hashlib.sha256(b).hexdigest()==item['sha256']
 p=d/name
 try:
  with p.open('xb') as f:f.write(b);f.flush();os.fsync(f.fileno())
 except FileExistsError:assert p.read_bytes()==b, 'Existing signed metadata differs'
 actual=p.read_bytes();assert hashlib.sha256(actual).hexdigest()==item['sha256']
 out[name]={'path':str(p),'sha256':item['sha256'],'bytes':len(actual)}
intent=Path('/dataset/shaoshitong/search-r1-rl/tree-grpo/instruct300/PROBABILITY_PROBE_ONCE-3268.json')
print(json.dumps({'host':socket.gethostname(),'files':out,'fixed_intent_exists':intent.exists(),'fixed_result_exists':Path(str(intent)+'.result.json').exists(),'assets_transferred':False},sort_keys=True))
